led test submissions","confidence":"high for observed changes; unresolved selection rule"},"source":"refine","created_at":"2026-09-29T12:47:23.025Z","updated_at":"2026-09-29T12:47:23.025Z","version":1},"applied":true}],"harnessStatePath":"/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-primeagentlearner-1790682263/attempts/f584a00acdda4d60937d1e953c54734b/system/state/agent/harness/harness_state.json","scope":"global"}
